31	void ConnectionEstablisher::run(ConnectionEstablisher::TryResult & result, std::string & fail_message)
32	{
33	    is_finished = false;
34	    SCOPE_EXIT(is_finished = true);
35	    try
36	    {
37	        result.entry = pool->get(*timeouts, settings, /* force_connected = */ false);
38	        AsyncCallbackSetter async_setter(&*result.entry, std::move(async_callback));
39	
40	        UInt64 server_revision = 0;
41	        if (table_to_check)
42	            server_revision = result.entry->getServerRevision(*timeouts);
43	
44	        if (!table_to_check || server_revision < DBMS_MIN_REVISION_WITH_TABLES_STATUS)
45	        {
46	            result.entry->forceConnected(*timeouts);
47	            result.is_usable = true;
48	            result.is_up_to_date = true;
49	            return;
50	        }
51	
52	        /// Only status of the remote table corresponding to the Distributed table is taken into account.
53	        /// TODO: request status for joined tables also.
54	        TablesStatusRequest status_request;
55	        status_request.tables.emplace(*table_to_check);
56	
57	        TablesStatusResponse status_response = result.entry->getTablesStatus(*timeouts, status_request);
58	        auto table_status_it = status_response.table_states_by_id.find(*table_to_check);
59	        if (table_status_it == status_response.table_states_by_id.end())
60	        {
61	            fail_message = fmt::format("There is no table {}.{} on server: {}",
62	                backQuote(table_to_check->database), backQuote(table_to_check->table), result.entry->getDescription());
63	            LOG_WARNING(log, fmt::runtime(fail_message));
64	            ProfileEvents::increment(ProfileEvents::DistributedConnectionMissingTable);
65	            return;
66	        }
67	
68	        result.is_usable = true;
69	
70	        UInt64 max_allowed_delay = settings ? UInt64(settings->max_replica_delay_for_distributed_queries) : 0;
71	        if (!max_allowed_delay)
72	        {
73	            result.is_up_to_date = true;
74	            return;
75	        }
76	
77	        UInt32 delay = table_status_it->second.absolute_delay;
78	
79	        if (delay < max_allowed_delay)
80	            result.is_up_to_date = true;
81	        else
82	        {
83	            result.is_up_to_date = false;
84	            result.staleness = delay;
85	
